parameters.jsCode:
const { exitCode, stderr, stdout } = $input.first().json;

try {
  if (exitCode !== 0) {
    throw new Error(stderr?.trim() || 'Impossible de lire le dossier.');
  }

  const files = JSON.parse(stdout);
  const names = new Set();

  if (!Array.isArray(files)) {
    throw new Error('La réponse doit contenir une liste de fichiers.');
  }

  for (const file of files) {
    if (
      !file ||
      typeof file.name !== 'string' ||
      file.name.length === 0 ||
      !Number.isSafeInteger(file.size) ||
      file.size < 0 ||
      typeof file.revision !== 'string' ||
      file.revision.length === 0 ||
      names.has(file.name)
    ) {
      throw new Error('Liste de fichiers invalide.');
    }

    names.add(file.name);
  }

  return [{ json: { ok: true, files } }];
} catch (error) {
  return [{
    json: {
      ok: false,
      message: error.message
    }
  }];
}
